import React, { FC, useState, useEffect } from 'react';
import ConfigureSplunkConfigFile, {
    IFormData,
    IForm,
    IProps as ConfigFormGeneratorProps,
} from '@splunk/config-form-generator';
import { ErrorMessagesType, Errors } from '@splunk/sui-form-renderer';
import { flowRight as compose, upperFirst } from 'lodash';
import WaitSpinner from '@splunk/react-ui/WaitSpinner';
import styled from 'styled-components';

import {
    withRBACFilter,
    withSplunkEnvFilter,
    withExperienceFilter,
} from '../../shared/components/FilterHOCs/filterHOCs';
import TokenAuthDisabled from '../../shared/components/TokenAuthDisabled/TokenAuthDisabled.component';
import {
    stanzaValues,
    fetchFormConfig,
    fetchConfigSettings,
    manageLimitsConfig,
} from './LimitsConfig.apiservice';
import { MESSAGES } from '../../messages';
import { UserService } from '../../shared/services/UserService';
import { LIMITS_CONFIG_LOC_STR } from './LimitsConfig.constants';
import TEST_IDS from './LimitsConfig.testids';
import ERRORS_CODES from '../../shared/services/UserService/errors';
import { ACSEnvironmentUrls } from '../../shared/services/UserService/UserService.interfaces';

const WaitSpinnerWrapper = styled.div`
    display: flex;
    justify-content: center;
    margin-top: 40px;
    margin-bottom: 40px;
`;

const ErrorWrapper = styled.div`
    margin-left: 25px;
    margin-right: 25px;
    margin-bottom: 25px;
`;

const LimitsConfig: FC = () => {
    const [formConfig, setFormConfig] = useState<IForm>();
    const [formData, setFormData] = useState<IFormData>({});
    const [errorMessages, setErrorMessages] = useState<ErrorMessagesType>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [tokenAuthEnabled, setTokenAuthEnabled] = useState(false);

    useEffect(() => {
        const initFormConfig = async (): Promise<void> => {
            setFormConfig(await fetchFormConfig());
        };

        const initConfigSettings = async (): Promise<void> => {
            const { records, error } = await fetchConfigSettings();
            setFormData(records);
            setErrorMessages(error);
        };

        const exec = async (): Promise<void> => {
            try {
                // Init UserService singleton to start ACS related page bootstrap
                await UserService.init('v2', ACSEnvironmentUrls.limits);
                setTokenAuthEnabled(true);
                await Promise.all([initFormConfig(), initConfigSettings()]);
            } catch (err) {
                const errorCodes = new Set([
                    ERRORS_CODES.STACK_ID_INVALID,
                    ERRORS_CODES.ACS_ENVIRONMENT_NOT_FOUND,
                    ERRORS_CODES.CANNOT_CREATE_JWT_TOKEN,
                ]);
                if (errorCodes.has(err.message)) {
                    setTokenAuthEnabled(true);
                    setErrorMessages([MESSAGES.USER_CONTEXT.ERRORS[err.message]]);
                } else if (err.message === ERRORS_CODES.TOKEN_AUTH_DISABLED) {
                    setTokenAuthEnabled(false);
                } else {
                    setErrorMessages([err.message]);
                }
            } finally {
                setIsLoading(false);
            }
        };

        exec();
    }, []);

    const updateErrMsgWithStanzaName = (errorMsgs: string[] = []): ErrorMessagesType => {
        const nonEmptyErrorMsgs: ErrorMessagesType = [];
        errorMsgs.forEach((errorMsg, index) => {
            if (!errorMsg) {
                return;
            }
            nonEmptyErrorMsgs.push({
                key: stanzaValues[index],
                value: upperFirst(errorMsg),
            });
        });
        return nonEmptyErrorMsgs;
    };

    const handleSubmit: ConfigFormGeneratorProps['onSubmit'] = async ({ data, successCb, failureCb }) => {
        const { records, error = [] } = await manageLimitsConfig(data);
        // If no records were updated, do nothing.
        if (!records && !error.length) {
            return;
        }
        // Update records only if present. For error cases, we don't want to re-render the forms to preserve the user input that caused errors.
        if (records) {
            setFormData(records);
        }
        if (error.length) {
            failureCb(updateErrMsgWithStanzaName(error));
        } else {
            successCb();
        }
    };

    return (
        <>
            {tokenAuthEnabled && !isLoading && (
                <>
                    {errorMessages.length > 0 && (
                        <ErrorWrapper>
                            <Errors errorMessages={errorMessages} />
                        </ErrorWrapper>
                    )}
                    {!errorMessages.length && (
                        <ConfigureSplunkConfigFile
                            formConfig={formConfig}
                            formData={formData}
                            onSubmit={handleSubmit}
                            docLocationString={LIMITS_CONFIG_LOC_STR}
                        />
                    )}
                </>
            )}
            {!tokenAuthEnabled && !isLoading && <TokenAuthDisabled />}
            {isLoading && (
                <WaitSpinnerWrapper data-test-name={TEST_IDS.WAITSPINNER}>
                    <WaitSpinner size="medium" />
                </WaitSpinnerWrapper>
            )}
        </>
    );
};

const LimitsConfigPage = compose([
    withExperienceFilter(['noah']),
    withSplunkEnvFilter(['cloud']),
    withRBACFilter(['edit_limits_conf']),
])(LimitsConfig);

export default LimitsConfigPage;
